# -*- coding: utf-8 -*-
"""kb_route.py — 分层检索路由：Agent 拿上下文包的**单一入口**。

它解决什么
----------
`CLAUDE.md` 的 §Agentic RAG 检索协议 写得很细（查询分解 / 多跳 / 检索-验证-综合 /
自适应深度 / 上下文预算），但**全是人工协议**——要靠 Agent 自觉逐步执行，
而且每一步都要自己判断「该查概念页还是来源页还是原文」「这条结论证据多强」。

本工具把那条协议变成**一次调用**，按证据分层级联检索并返回带引用的上下文包：

    L0  manifest   库的规模与分层（回答「这个库有什么」）
    L1  concept / entity / topic    综合层：定义、机制、共识（检索枢纽）
    L2  source                      文献卡层：单篇主张、可靠性、SI 状态
    L3  corpus                      **原文块**：可直接回指 raw 的行号，带来源页限定词

分层而不是混排的意义：概念页与原文块的可信度**不是一回事**。
L1 是「本库的当前综合」，L3 是「某篇论文某一段的字面表述」——
混在一起排序，Agent 会把二手综合当一手证据用。

用法
----
    python tools/kb_route.py "固态电解质 界面 稳定性"
    python tools/kb_route.py "锂沉积效率" --budget 5,5,8 --json
    python tools/kb_route.py "锌负极" --layer 1            # 只看综合层
    python tools/kb_route.py "..." --no-corpus            # 跳过原文层（快）
    python tools/kb_route.py --selftest
"""

import os
import sys
import json
import argparse

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import kb_lib as K

DEFAULT_BUDGET = {"L1": 5, "L2": 5, "L3": 8}

# 类型 → wiki 子目录（**不能加 s 拼接**：entity → "entitys" 不存在，正确是 entities。
# 这个坑在 kb_search.py 里已经踩过一次，此处一并显式化。）
TYPE_DIR = {"concept": "concepts", "entity": "entities", "source": "sources",
            "topic": "topics", "output": "outputs"}


def _cite(name, ptype):
    d = TYPE_DIR.get(ptype)
    return f"[[{d}/{name}]]" if d else f"[[{name}]]"


def _meta_and_bm():
    import kb_search as KS
    return KS, KS.load_index()


def layer1(query, k, KS, meta, bm):
    """综合层：concept / entity / topic。"""
    alias_hits = KS.resolve_aliases(query, meta.get("alias_map", {}))
    strong = [(a, c) for a, c in alias_hits if len(a) >= 3] or alias_hits[:1]
    canon = [c for _, c in strong]
    qt = K.tokenize(query)
    for c in canon:
        qt.extend(K.tokenize(c))
    for a, c in alias_hits:
        if c not in canon:
            qt.extend(K.tokenize(c))
    ranked = KS.bm25_score(qt, bm, canon, query_raw=query)
    out = []
    for name, score in ranked:
        s, u, tags, al, t = KS.meta_of(meta, name)
        if t not in ("concept", "entity", "topic"):
            continue
        out.append({"layer": "L1", "name": name, "type": t,
                    "score": round(score, 3), "summary": s,
                    "citation": _cite(name, t),
                    "path": KS.page_path(name, t)})
        if len(out) >= k:
            break
    return out


def layer2(query, k, KS, meta, bm):
    """文献卡层：source。"""
    alias_hits = KS.resolve_aliases(query, meta.get("alias_map", {}))
    strong = [(a, c) for a, c in alias_hits if len(a) >= 3] or alias_hits[:1]
    canon = [c for _, c in strong]
    qt = K.tokenize(query)
    for c in canon:
        qt.extend(K.tokenize(c))
    ranked = KS.bm25_score(qt, bm, canon, query_raw=query)
    out = []
    for name, score in ranked:
        s, u, tags, al, t = KS.meta_of(meta, name)
        if t != "source":
            continue
        # 补来源可靠性（检索层一直没用上的字段）
        rel = ""
        p = os.path.join(K.WIKI, "sources", name + ".md")
        if os.path.exists(p):
            fmr, _ = K.split_frontmatter(K.read_text(p))
            fm = K.parse_frontmatter(fmr)
            rel = str(fm.get("source_reliability") or "")[:160]
        out.append({"layer": "L2", "name": name, "type": t,
                    "score": round(score, 3), "summary": s,
                    "source_reliability": rel,
                    "citation": f"[[sources/{name}]]",
                    "path": KS.page_path(name, t)})
        if len(out) >= k:
            break
    return out


def layer3(query, k):
    """原文层：raw 全文块。"""
    try:
        import kb_corpus as C
    except ImportError:
        return []
    try:
        return [dict(r, layer="L3",
                     citation=f"`{r['path']}`:{r['line_start']}-{r['line_end']}")
                for r in C.search(query, k=k)]
    except FileNotFoundError:
        return []


def route(query, budget=None, layers=(1, 2, 3)):
    """按层检索并组装上下文包。"""
    budget = dict(DEFAULT_BUDGET, **(budget or {}))
    KS, (meta, bm) = _meta_and_bm()
    pkg = {
        "query": query,
        "L0": {
            "pages": meta.get("count"),
            "alias_entries": len(meta.get("alias_map", {})),
            "note": ("分层检索：L1 综合（概念/实体/主题）→ L2 文献卡 → L3 原文块。"
                     "各层证据强度不同，勿把 L1 的综合结论当作一手证据。"),
        },
        "L1": [], "L2": [], "L3": [],
    }
    if 1 in layers:
        pkg["L1"] = layer1(query, budget["L1"], KS, meta, bm)
    if 2 in layers:
        pkg["L2"] = layer2(query, budget["L2"], KS, meta, bm)
    if 3 in layers:
        pkg["L3"] = layer3(query, budget["L3"])
    pkg["counts"] = {k: len(pkg[k]) for k in ("L1", "L2", "L3")}
    # 相关性信号：BM25 **没有分数下限**，任何查询都会凑满 k 条。
    # 不给出这个信号，Agent 就无法区分「确实命中」与「勉强凑数」。
    tops = {lv: (max((x.get("score", 0) for x in pkg[lv]), default=0.0))
            for lv in ("L1", "L2", "L3")}
    pkg["signal"] = {
        "top_score": {k: round(v, 3) for k, v in tops.items()},
        "low_confidence": all(v < 3.0 for v in tops.values() if v),
        "note": ("top_score 为各层最高 BM25 分；普遍 <3 通常意味着该查询"
                 "在库内没有强命中，应改用不同术语或视为知识空白。"),
    }
    # 建议阅读集：把最强命中按层拼一条最小充分路径
    pkg["suggested_read"] = ([x["path"] for x in pkg["L1"][:2]]
                             + [x["path"] for x in pkg["L2"][:2]])
    return pkg


def selftest():
    print("=== kb_route --selftest ===")
    ok = True
    p = route("固态电解质界面稳定性", layers=(1, 2))
    print(f"  L1={p['counts']['L1']}  L2={p['counts']['L2']}")
    # 召回断言只对**有内容**的库成立；空库 0 召回是正确行为（不是故障）。
    try:
        _meta, _bm = _meta_and_bm()[1]
        _n_pages = _bm.get("n_docs", 1)
    except Exception:                                      # noqa: BLE001
        _n_pages = 1
    if _n_pages > 0:
        good = p["counts"]["L1"] > 0 and p["counts"]["L2"] > 0
        print(f"  [{'ok' if good else 'FAIL'}] L1/L2 都能召回")
        ok = ok and good
    else:
        print("  [skip] 空库：无内容可召回（分层管道已跑通）")
    # 分层纯净性：L1 只含综合层类型，L2 只含 source
    l1_types = {x["type"] for x in p["L1"]}
    l2_types = {x["type"] for x in p["L2"]}
    good2 = l1_types <= {"concept", "entity", "topic"} and l2_types <= {"source"}
    print(f"  [{'ok' if good2 else 'FAIL'}] 分层纯净 L1={l1_types} L2={l2_types}")
    ok = ok and good2
    # 每条都带 citation 与真实路径
    bad = [x for lv in ("L1", "L2") for x in p[lv]
           if not x.get("citation") or not x.get("path")
           or not os.path.exists(os.path.join(K.VAULT, x["path"]))]
    print(f"  [{'ok' if not bad else 'FAIL'}] 每条都有 citation 且路径真实存在"
          f"（坏条目 {len(bad)}）")
    ok = ok and not bad
    # 反例：纯乱码查询不得返回 L1 结果（不应硬凑）
    p2 = route("zzzqqq不存在的术语xyz", layers=(1,))
    print(f"  [{'ok' if p2['counts']['L1'] == 0 else 'info'}] 乱码查询 L1 返回 "
          f"{p2['counts']['L1']} 条；top_score={p2['signal']['top_score']['L1']} "
          f"low_confidence={p2['signal']['low_confidence']}")
    good_sig = "signal" in p2 and "top_score" in p2["signal"]
    print(f"  [{'ok' if good_sig else 'FAIL'}] 始终给出相关性信号"
          f"（BM25 无分数下限，Agent 需要它区分「命中」与「凑数」）")
    ok = ok and good_sig
    # --layer 生效
    p3 = route("固态电解质", layers=(1,))
    good3 = p3["counts"]["L2"] == 0 and p3["counts"]["L3"] == 0
    print(f"  [{'ok' if good3 else 'FAIL'}] --layer 限制生效（仅 L1）")
    ok = ok and good3
    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def main():
    ap = argparse.ArgumentParser(description="分层检索路由（Agent 入口）")
    ap.add_argument("query", nargs="?", default="")
    ap.add_argument("--budget", default="", help="L1,L2,L3 条数，如 5,5,8")
    ap.add_argument("--layer", default="", help="只跑指定层，如 1 或 1,2")
    ap.add_argument("--no-corpus", action="store_true")
    ap.add_argument("--json", action="store_true")
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args()

    if args.selftest:
        return selftest()
    if not args.query:
        ap.print_help()
        return 1

    # 解析走 kb_lib 的单一实现（此前本文件与 kb.py / kb_serve.py 各有一份拷贝）。
    budget = K.parse_budget(args.budget)
    layers = K.parse_layers(args.layer)
    if not args.layer and args.no_corpus:
        layers = (1, 2)

    pkg = route(args.query, budget=budget, layers=layers)

    if args.json:
        print(json.dumps(pkg, ensure_ascii=False, indent=1))
        return 0

    print("=" * 70)
    print(f'  上下文包  "{args.query}"')
    print("=" * 70)
    print(f"库: {pkg['L0']['pages']} 页  别名 {pkg['L0']['alias_entries']} 条")
    print(f"命中: L1 {pkg['counts']['L1']} / L2 {pkg['counts']['L2']}"
          f" / L3 {pkg['counts']['L3']}")
    if pkg["L1"]:
        print("\n— L1 综合层（定义 / 机制 / 共识）—")
        for x in pkg["L1"]:
            print(f"  [{x['type']}] {x['citation']}   ({x['score']})")
            if x.get("summary"):
                print(f"      {x['summary'][:150]}")
    if pkg["L2"]:
        print("\n— L2 文献卡层（单篇主张 / 可靠性）—")
        for x in pkg["L2"]:
            print(f"  {x['citation']}   ({x['score']})")
            if x.get("source_reliability"):
                print(f"      可靠性: {x['source_reliability'][:130]}")
            if x.get("summary"):
                print(f"      {x['summary'][:130]}")
    if pkg["L3"]:
        print("\n— L3 原文层（可回指 raw 行号，带来源页限定词）—")
        for x in pkg["L3"]:
            print(f"  {x['citation']}   ({x['score']})")
            if x.get("heading"):
                print(f"      § {x['heading']}")
            if x.get("source_page"):
                bits = [f"来源页 [[sources/{x['source_page']}]]"]
                if x.get("source_reliability"):
                    bits.append(f"可靠性={x['source_reliability'][:70]}")
                print("      " + "  ".join(bits))
            print(f"      {x['snippet'][:170]}...")
    if pkg["suggested_read"]:
        print("\n建议阅读集：")
        for p in pkg["suggested_read"]:
            print(f"  {p}")
    return 0


if __name__ == "__main__":
    try:
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")
    except Exception:
        pass
    sys.exit(main())
